/**
 * Errors a `Planner` call can throw.
 */
public 
enum PlannerError: Swift.Error, Equatable, Hashable, Foundation.LocalizedError {

    
    
    /**
     * Required data isn't loaded yet: either the Region Pack failed to
     * open, or `plan()`/`energy()` was called before `load_chargers`.
     */
    case PackMissing(message: String
    )
    case InvalidRequest(message: String
    )
    case NoRouteFound(message: String
    )
    /**
     * The caller's `cancel()` was observed before the Plan completed.
     */
    case Cancelled(message: String
    )

    

    

    
    public var errorDescription: String? {
        String(reflecting: self)
    }
    
}

#if compiler(>=6)
extension PlannerError: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypePlannerError: FfiConverterRustBuffer {
    typealias SwiftType = PlannerError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> PlannerError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .PackMissing(
            message: try FfiConverterString.read(from: &buf)
            )
        case 2: return .InvalidRequest(
            message: try FfiConverterString.read(from: &buf)
            )
        case 3: return .NoRouteFound(
            message: try FfiConverterString.read(from: &buf)
            )
        case 4: return .Cancelled(
            message: try FfiConverterString.read(from: &buf)
            )

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: PlannerError, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case let .PackMissing(message):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(message, into: &buf)
            
        
        case let .InvalidRequest(message):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(message, into: &buf)
            
        
        case let .NoRouteFound(message):
            writeInt(&buf, Int32(3))
            FfiConverterString.write(message, into: &buf)
            
        
        case let .Cancelled(message):
            writeInt(&buf, Int32(4))
            FfiConverterString.write(message, into: &buf)
            
        }
    }
}


